30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** Dedicated audit logger; emits an audit line on successful owner create. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
135	        LocalDate registrationDate = owner.getRegistrationDate();
136	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getRegistrationDate)
138	            .filter(registrationDate::equals)
139	            .count();
140	        if (ownersCreatedThatDay >= 100) {
141	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
142	        }
143	        String address = addressNormalizer.normalize(owner.getAddress());
144	        if (address.isBlank()) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setAddress(address);
148	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
149	        if (telephone == null) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        owner.setTelephone(telephone);
153	        String email = owner.getEmail();
154	        if (email != null) {
155	            email = email.trim();
156	            if (!EMAIL_PATTERN.matcher(email).matches()) {
157	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	            }
159	            owner.setEmail(email.toLowerCase(Locale.ROOT));
160	        }
161	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
162	            .map(Owner::getTelephone)
163	            .filter(Objects::nonNull)
164	            .map(telephoneNormalizer::normalize)
165	            .anyMatch(telephone::equals);
166	        if (telephoneInUse) {
167	            return new ResponseEntity<>(HttpStatus.CONFLICT);
168	        }
169	        String cityKey = normalizeIdentity(owner.getCity());
170	        long ownersInCity = this.clinicService.findAllOwners().stream()
171	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
172	            .count();
173	        if (ownersInCity >= 50) {
174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
175	        }
176	        String lastNameKey = normalizeIdentity(owner.getLastName());
177	        String addressKey = addressNormalizer.normalize(owner.getAddress());
178	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
179	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
180	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
181	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
182	            if (householdDuplicate) {
183	                return new ResponseEntity<>(HttpStatus.CONFLICT);
184	            }
185	        }
186	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
187	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
188	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
189	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
190	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
191	            .count();
192	        owner.setNamesakeCount(namesakeCount);
193	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
194	        this.clinicService.saveOwner(owner);
195	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    /**
204	     * Normalize a value for household-identity comparison: null becomes an empty
205	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
206	     * to a single space, and the result is lower-cased.
207	     */
208	    private static String normalizeIdentity(String value) {
209	        if (value == null) {
210	            return "";
211	        }
212	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
213	    }
214	
215	    /**
216	     * Build the stable, shared household identifier for an owner, formatted
217	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
218	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
219	     * Owners in the same household (same normalized lastName and address) therefore
220	     * derive an identical householdId.
221	     */
222	    private static String householdId(String lastNameKey, String addressKey) {
223	        String source = lastNameKey + "|" + addressKey;
224	        try {
225	            byte[] digest = MessageDigest.getInstance("SHA-256")
226	                .digest(source.getBytes(StandardCharsets.UTF_8));
227	            StringBuilder sb = new StringBuilder(digest.length * 2);
228	            for (byte b : digest) {
229	                sb.append(String.format("%02x", b));
230	            }
231	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
232	        }
233	        catch (NoSuchAlgorithmException e) {
234	            throw new IllegalStateException("SHA-256 not available", e);
235	        }
236	    }
237	
238	    /**
239	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
240	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
241	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
242	     * sequence equal to one more than the number of owners already in that city
243	     * (e.g. 'LON-SMI-0007').
244	     */
245	    private String nextCustomerCode(String city, String lastName) {
246	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
247	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
248	        String cityKey = normalizeIdentity(city);
249	        int sequence = (int) this.clinicService.findAllOwners().stream()
250	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
251	            .count() + 1;
252	        return String.format("%s-%s-%04d", city3, last3, sequence);
253	    }
254	
255	    /**
256	     * Roll a registration date forward to the next business day: a Saturday or Sunday
257	     * advances to the following Monday, and a weekday is returned unchanged.
258	     */
259	    private static LocalDate toBusinessDay(LocalDate date) {
260	        return switch (date.getDayOfWeek()) {
261	            case SATURDAY -> date.plusDays(2);
262	            case SUNDAY -> date.plusDays(1);
263	            default -> date;
264	        };
265	    }
266	
267	    /**
268	     * Build the membership number assigned on create, formatted
269	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
270	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
271	     */
272	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
273	        String yy = String.format("%02d", registrationDate.getYear() % 100);
274	        return customerCode + "-M" + yy;
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
280	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
281	        if (currentOwner == null) {
282	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	        }
284	        currentOwner.setAddress(ownerFieldsDto.getAddress());
285	        currentOwner.setCity(ownerFieldsDto.getCity());
286	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
287	        currentOwner.setLastName(ownerFieldsDto.getLastName());
288	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
289	        this.clinicService.saveOwner(currentOwner);
290	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Transactional
295	    @Override
296	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner == null) {
299	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	        }
301	        this.clinicService.deleteOwner(owner);
302	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
303	    }
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
308	        Owner owner = this.clinicService.findOwnerById(ownerId);
309	        if (owner == null) {
310	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
311	        }
312	        HttpHeaders headers = new HttpHeaders();
313	        Pet pet = petMapper.toPet(petFieldsDto);
314	        owner.setId(ownerId);
315	        pet.setOwner(owner);
316	        pet.getType().setName(null);
317	        this.clinicService.savePet(pet);
318	        PetDto petDto = petMapper.toPetDto(pet);
319	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
320	            .buildAndExpand(pet.getId()).toUri());
321	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
322	    }
323	
324	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
325	    @Override
326	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
327	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
328	        if (currentOwner != null) {
329	            Pet currentPet = this.clinicService.findPetById(petId);
330	            if (currentPet != null) {
331	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
332	                currentPet.setName(petFieldsDto.getName());
333	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
334	                this.clinicService.savePet(currentPet);
335	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
336	            }
337	        }
338	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	    }
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
344	        HttpHeaders headers = new HttpHeaders();
345	        Visit visit = visitMapper.toVisit(visitFieldsDto);
346	        Pet pet = new Pet();
347	        pet.setId(petId);
348	        visit.setPet(pet);
349	        this.clinicService.saveVisit(visit);
350	        VisitDto visitDto = visitMapper.toVisitDto(visit);
351	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
352	            .buildAndExpand(visit.getId()).toUri());
353	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
354	    }
355	
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
360	        Owner owner = this.clinicService.findOwnerById(ownerId);
361	        if (owner != null) {
362	            Pet pet = owner.getPet(petId);
363	            if (pet != null) {
364	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
365	            }
366	        }
367	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
368	    }
369	}
